    @T.prim_func(private=True)
    def NT_matmul(var_rms_norm389: T.handle, var_lv198: T.handle, var_NT_matmul: T.handle):
        T.func_attr({"tir.noalias": True})
        batch_size = T.int64()
        rms_norm389 = T.match_buffer(var_rms_norm389, (batch_size, T.int64(1), T.int64(4096)), "float16")
        vocab_size = T.int64()
        lv198 = T.match_buffer(var_lv198, (vocab_size, T.int64(4096)), "float16")
        NT_matmul = T.match_buffer(var_NT_matmul, (batch_size, T.int64(1), vocab_size), "float16")
        # with T.block("root"):
        for i0, i1, i2, k in T.grid(batch_size, T.int64(1), vocab_size, T.int64(4096)):
            with T.block("NT_matmul"):
                v_i0, v_i1, v_i2, v_k = T.axis.remap("SSSR", [i0, i1, i2, k])
                T.reads(rms_norm389[v_i0, v_i1, v_k], lv198[v_i2, v_k])
                T.writes(NT_matmul[v_i0, v_i1, v_i2])
                with T.init():
                    NT_matmul[v_i0, v_i1, v_i2] = T.float16(0.0)
                NT_matmul[v_i0, v_i1, v_i2] = NT_matmul[v_i0, v_i1, v_i2] + rms_norm389[v_i0, v_i1, v_k] * lv198[v_i2, v_k]

